-- Schema for database: schemabench_0198
CREATE TABLE `cookie` (
  `cookie_id` int(11) NOT NULL,
  `user_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`cookie_id`),
  KEY `cookie_ibfk_1` (`user_id`),
  CONSTRAINT `cookie_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `user` (`user_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `event` (
  `event_id` int(11) NOT NULL AUTO_INCREMENT,
  `cookie_id` int(11) NOT NULL,
  `event_type` varchar(255) NOT NULL,
  `event_identifier` varchar(255) NOT NULL,
  `page_id` int(11) NOT NULL,
  PRIMARY KEY (`event_id`),
  KEY `event_ibfk_1` (`cookie_id`),
  CONSTRAINT `event_ibfk_1` FOREIGN KEY (`cookie_id`) REFERENCES `cookie` (`cookie_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `page_hierarchy` (
  `page_id` int(11) NOT NULL,
  `parent_page_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`page_id`),
  KEY `page_hierarchy_ibfk_1` (`parent_page_id`),
  CONSTRAINT `page_hierarchy_ibfk_1` FOREIGN KEY (`parent_page_id`) REFERENCES `page_hierarchy` (`page_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `campaign` (
  `campaign_id` int(11) NOT NULL,
  `campaign_identifier` varchar(255) NOT NULL,
  PRIMARY KEY (`campaign_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `user` (
  `user_id` int(11) NOT NULL,
  `name` varchar(255) NOT NULL,
  PRIMARY KEY (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `page` (
  `page_id` int(11) NOT NULL,
  `page_name` varchar(255) NOT NULL,
  PRIMARY KEY (`page_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
